#include <inttypes.h>
#include <openssl/sha.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *rname[32]={"zero","at","v0","v1","a0","a1","a2","a3","t0","t1","t2","t3","t4","t5","t6","t7","s0","s1","s2","s3","s4","s5","s6","s7","t8","t9","k0","k1","gp","sp","fp","ra"};
static uint32_t le32(const uint8_t*p){return p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint8_t*slurp(const char*p,size_t*n){FILE*f=fopen(p,"rb");long z;uint8_t*b;if(!f){perror(p);exit(2);}fseek(f,0,SEEK_END);z=ftell(f);rewind(f);b=malloc((size_t)z);if(!b||fread(b,1,(size_t)z,f)!=(size_t)z)exit(2);fclose(f);*n=(size_t)z;return b;}
static uint32_t wat(const uint8_t*b,size_t n,uint32_t load,uint32_t pc){uint64_t o=0x800ull+(uint64_t)pc-load;if(o+4>n){fprintf(stderr,"bad pc 0x%08x\n",pc);exit(3);}return le32(b+o);}
static const char*memop(unsigned op){switch(op){case 0x20:return"lb";case 0x21:return"lh";case 0x23:return"lw";case 0x24:return"lbu";case 0x25:return"lhu";case 0x28:return"sb";case 0x29:return"sh";case 0x2b:return"sw";default:return NULL;}}
static void dec(uint32_t pc,uint32_t w){unsigned op=w>>26,rs=w>>21&31,rt=w>>16&31,rd=w>>11&31,fn=w&63;int16_t im=(int16_t)w;const char*m;if(!w){printf("nop");return;}if(!op){if(fn==8)printf("jr $%s",rname[rs]);else if(fn==0x21)printf("addu $%s,$%s,$%s",rname[rd],rname[rs],rname[rt]);else if(fn==0x23)printf("subu $%s,$%s,$%s",rname[rd],rname[rs],rname[rt]);else if(fn==0)printf("sll $%s,$%s,%u",rname[rd],rname[rt],(w>>6)&31);else printf("special 0x%x",fn);return;}if(op==2||op==3){printf("%s 0x%08x",op==3?"jal":"j",((pc+4)&0xf0000000u)|((w&0x3ffffffu)<<2));return;}if(op>=4&&op<=7){static const char*n[]={"beq","bne","blez","bgtz"};uint32_t t=pc+4+((int32_t)im<<2);if(op<6)printf("%s $%s,$%s,0x%08x",n[op-4],rname[rs],rname[rt],t);else printf("%s $%s,0x%08x",n[op-4],rname[rs],t);return;}if(op==1){printf("regimm rt=%u $%s,0x%08x",rt,rname[rs],pc+4+((int32_t)im<<2));return;}if(op==9){printf("addiu $%s,$%s,%d",rname[rt],rname[rs],im);return;}if(op==0xa||op==0xb){printf("%s $%s,$%s,%d",op==0xa?"slti":"sltiu",rname[rt],rname[rs],im);return;}if(op==0xc||op==0xd){printf("%s $%s,$%s,0x%x",op==0xc?"andi":"ori",rname[rt],rname[rs],(uint16_t)im);return;}if(op==0xf){printf("lui $%s,0x%x",rname[rt],(uint16_t)im);return;}if((m=memop(op))){printf("%s $%s,%d($%s)",m,rname[rt],im,rname[rs]);return;}printf("op=0x%x",op);}
static void dump(const uint8_t*b,size_t n,uint32_t load,uint32_t a,uint32_t z){for(uint32_t pc=a;pc<=z;pc+=4){uint32_t w=wat(b,n,load,pc);printf("0x%08x  %08x  ",pc,w);dec(pc,w);putchar('\n');}}
int main(int ac,char**av){size_t n;uint8_t*b,h[32];if(ac!=2)return 2;b=slurp(av[1],&n);if(n<0x800||memcmp(b,"PS-X EXE",8))return 3;uint32_t load=le32(b+0x18),sz=le32(b+0x1c);SHA256(b,n,h);printf("sha256=");for(int i=0;i<32;i++)printf("%02x",h[i]);printf(" load=0x%08x payload=%u\n",load,sz);puts("A13_CROSS_REGION_FOR_SEPARATION");dump(b,n,load,0x80047a80u,0x80047b70u);puts("TRIANGLE_MASK_SITES_IN_PLAYER_CONTACT");unsigned tri=0;for(uint32_t pc=0x80047284u;pc<0x80048138u;pc+=4){uint32_t w=wat(b,n,load,pc);if((w>>26)==0x0c&&(uint16_t)w==0x1000){printf("triangle_mask pc=0x%08x\n",pc);dump(b,n,load,pc-32,pc+180);tri++;}}puts("BYTE_OFFSET_0E_ACCESSES");unsigned loads=0,stores=0,packrefs=0;for(uint32_t pc=load;pc<load+sz;pc+=4){uint32_t w=wat(b,n,load,pc);unsigned op=w>>26;if((uint16_t)w==0x0196&&(op>=0x20&&op<=0x2b)){printf("pack_ref pc=0x%08x word=%08x op=0x%x\n",pc,w,op);packrefs++;}if((int16_t)w!=14)continue;if(op==0x20||op==0x24){printf("load pc=0x%08x word=%08x\n",pc,w);loads++;}else if(op==0x28){printf("store pc=0x%08x word=%08x\n",pc,w);stores++;}}puts("COLOR_RGB_TABLE_80078E58");for(unsigned i=0;i<16;i++){uint32_t a=0x80078e58u+3u*i;uint64_t o=0x800ull+(uint64_t)a-load;printf("color=%u rgb=(%u,%u,%u)\n",i,b[o],b[o+1],b[o+2]);}puts("PACK_CONSUMERS_AND_WRITERS");dump(b,n,load,0x80054360u,0x80054530u);puts("PACK_SCENE_RESET");dump(b,n,load,0x8005bb40u,0x8005bb70u);printf("SUMMARY triangle_masks=%u byte0e_loads=%u byte0e_stores=%u pack_refs=%u\n",tri,loads,stores,packrefs);free(b);return 0;}
